UPDATE counterparties c SET display_name = ranked.display_name FROM ( SELECT effective_cp, (array_agg(display_name ORDER BY cnt DESC, last_booking DESC, display_name ASC))[1] AS display_name FROM ( SELECT COALESCE(al.canonical_counterparty_id, own.id) AS effective_cp, identified.normalized_display AS display_name, count(*) AS cnt, max(identified.booking_date) AS last_booking FROM ( SELECT CASE WHEN attributed_name IS NOT NULL THEN 'name' WHEN creditor_id IS NOT NULL THEN 'creditor_id' WHEN counterparty_iban IS NOT NULL THEN 'iban' WHEN normalized_name <> '' THEN 'name' END AS identity_type, CASE WHEN attributed_name IS NOT NULL THEN upper(normalized_attributed) WHEN creditor_id IS NOT NULL THEN creditor_id WHEN counterparty_iban IS NOT NULL THEN counterparty_iban WHEN normalized_name <> '' THEN upper(normalized_name) END AS identity_value, normalized_display, booking_date FROM ( SELECT creditor_id, counterparty_iban, attributed_name, trim(regexp_replace( normalize(counterparty_name, NFC), '\s+', ' ', 'g' )) AS normalized_name, trim(regexp_replace( normalize(attributed_name, NFC), '\s+', ' ', 'g' )) AS normalized_attributed, trim(regexp_replace( normalize(COALESCE(attributed_name, counterparty_name), NFC), '\s+', ' ', 'g' )) AS normalized_display, booking_date FROM transactions WHERE split_parent_content_hash IS NULL ) normalized ) identified LEFT JOIN counterparty_alias al ON al.identity_type = identified.identity_type AND al.identity_value = identified.identity_value LEFT JOIN counterparties own ON own.identity_type = identified.identity_type AND own.identity_value = identified.identity_value WHERE identified.identity_type IS NOT NULL AND identified.normalized_display <> '' GROUP BY effective_cp, identified.normalized_display ) per_name WHERE effective_cp IS NOT NULL GROUP BY effective_cp ) ranked WHERE c.id = ranked.effective_cp AND c.merged_into IS NULL AND c.display_name IS DISTINCT FROM ranked.display_name
